__global__ void scale(float *data, float factor, int n) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i < n) {
    data[i] = data[i] * factor;
  }
}

__global__ void reverseBlock(int *data) {
  __shared__ int temp[256];
  int tid = threadIdx.x;
  temp[tid] = data[tid];
  __syncthreads();
  data[tid] = temp[255 - tid];
}
